<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Generate Admission Letter</h1><p>Select a persisted student and print the admission record.</p></div></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Search Student</label><input class="module-input" name="q" value="<?= e($search) ?>"></div><div class="module-field"><label>Select Student</label><select class="module-select" name="student_id" required><option value="">Select Student</option><?php foreach($students as$s):?><option value="<?= $s['id'] ?>" <?= ($student['id']??0)==$s['id']?'selected':'' ?>><?= e($s['registration_no'].' — '.$s['student_name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary" type="submit">Generate</button></form><?php if($student):?><section class="module-card print-sheet"><header class="module-card__header"><div><h2><?= e($institute['name']) ?></h2><p><?= e($institute['address']) ?> · <?= e($institute['phone']) ?></p></div><button class="btn btn--primary" type="button" onclick="window.print()">Print</button></header><div class="module-card__body"><h2>Admission Letter</h2><p>This confirms that <strong><?= e($student['student_name']) ?></strong>, registration <strong><?= e($student['registration_no']) ?></strong>, was admitted to <strong><?= e($student['class_name']) ?></strong> on <?= e($student['date_of_admission']) ?>.</p><p>Father/Guardian: <?= e($student['father_name']?:'—') ?> · Contact: <?= e($student['father_mobile']?:$student['mobile']?:'—') ?></p><?php if(!empty($rules['student'])):?><hr><h3>Rules &amp; Regulations</h3><div><?= $rules['student'] ?></div><?php endif ?></div></section><?php endif ?></div></div></main>
